"""Supply copy delivery examples while preserving native tool selection."""

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


SKILL_NAME = "coffee-copy-delivery"
SKILL_SOURCE = "curator-capability"
SKILL_ASSET = "skills/coffee-copy-delivery/SKILL.md"

GUIDANCE = """处理咖啡豆新批次介绍时：
1. 先确认本次工作规则、当批杯测表和风味词总表；已完整可见且未变化的材料直接使用，缺漏或截断才补读。换品牌、批次或版本重新确认，不沿用旧批要求。
2. 以本次规则决定语气、自称、禁词、风味表达、篇幅、分段和事实范围；区分本批实测与词表可用表达，不从词表或备注擅自增加风味，不补没有依据的产地、处理法、风味或其他具体事实。当前规则允许的表达不要套用旧批限制。
3. 对照已展示的 coffee-copy-delivery 方法，无需另读。先完成含实际换行和当次完整冲煮结尾的一份正文。用现有 exec 在同一次本地核算中，按本次规则计算并比较总字数和逐段句数：满足机械要求且正文非空时只原样输出整份正文，不输出统计、成功说明或“正文：”标签；不满足时只返回修改所需的诊断，修正文后再核新稿，不重复核未改变的合格稿。成功且完整返回后，最终回复只沿用这份正文及其换行，不另写交稿汇报，也不复制工具的退出码或包装，不另附同文文件。失败与不可用的处理见方法，不能把它们当作通过。
4. 普通核对问题删改后继续交付可靠正文，不用计划或说明代替。关键材料不足先补读，仍不足可靠成文才说明必要缺口，不猜测。真实发布与正文交付分开：用户要求发布且真实入口、权限及条件具备时沿现有能力发布同一份定稿，不绕过权限，不把生成正文当作已发布，不虚构成功；入口不可用或发布失败不阻断可靠正文交付。"""


class CoffeeCopyCapability(CapabilityStrategy):
    """Prepare one example skill and select its body beside other skill entries."""

    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        if SKILL_ASSET not in request.assets:
            raise ValueError(f"Required delivery example asset is missing: {SKILL_ASSET}")
        return (
            SkillContribution(
                name=SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": request.assets[SKILL_ASSET]},
                source="coffee-copy-delivery-examples",
            ),
        )

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        identity = (SKILL_SOURCE, SKILL_NAME)
        matches = [
            skill for skill in request.skills
            if (skill.source, skill.name) == identity
        ]
        if not matches:
            raise ValueError(f"Required delivery example skill is missing: {SKILL_SOURCE}/{SKILL_NAME}")
        if len(matches) != 1:
            raise ValueError(f"Delivery example skill identity is ambiguous: {SKILL_SOURCE}/{SKILL_NAME}")
        if not matches[0].available:
            raise ValueError(f"Required delivery example skill is unavailable: {SKILL_SOURCE}/{SKILL_NAME}")

        selections: list[SkillSelection] = []
        seen: set[tuple[str, str]] = set()
        for skill in request.skills:
            key = (skill.source, skill.name)
            if not skill.available or key in seen:
                continue
            seen.add(key)
            selections.append(
                SkillSelection(
                    name=skill.name,
                    source=skill.source,
                    delivery="body" if key == identity else "catalog",
                )
            )
        # Explicit skill delivery replaces native skill text; tools stay delegated.
        return CapabilitySelection(tools=None, skills=tuple(selections), guidance=GUIDANCE)


def create(
    state: dict[str, JsonValue],
    task: Task,
    *,
    registrar: CapabilityRegistrar,
) -> CoffeeCopyCapability:
    # The host retains task identity and checkpoint; no business state is copied.
    return CoffeeCopyCapability(registrar)
